    "id" TEXT NOT NULL,
    "service_id" TEXT NOT NULL,
    "description" TEXT NOT NULL,

    CONSTRAINT "service_acceptance_criteria_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "qc_checklist_templates" (
    "id" TEXT NOT NULL,
    "service_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,

    CONSTRAINT "qc_checklist_templates_pkey" PRIMARY KEY ("id")
);

ALTER TABLE "escrow_holds"
ADD COLUMN "released_amount" INTEGER NOT NULL DEFAULT 0,
ADD COLUMN "refunded_amount" INTEGER NOT NULL DEFAULT 0;

ALTER TABLE "orders"
  ADD COLUMN "package_snapshot" JSONB,
  ADD COLUMN "version" INTEGER NOT NULL DEFAULT 0;

ALTER TABLE "executor_profiles"
  ADD COLUMN "shaba_number" TEXT,
  ADD COLUMN "shaba_verified_at" TIMESTAMP(3);

ALTER TABLE "order_milestones"
  ADD COLUMN "delivered_at" TIMESTAMP(3),
  ADD COLUMN "approved_at" TIMESTAMP(3);

UPDATE "idempotency_keys"
SET "request_hash" = encode(digest("scope" || ':' || "key", 'sha256'), 'hex'),
    "expires_at" = "created_at" + INTERVAL '24 hours';

ALTER TABLE "idempotency_keys"
  ALTER COLUMN "request_hash" SET NOT NULL,
  ALTER COLUMN "expires_at" SET NOT NULL;

ALTER TABLE "ledger_entries"
  ADD CONSTRAINT "ledger_entries_amount_positive" CHECK ("amount" > 0),
  ADD CONSTRAINT "ledger_entries_accounts_distinct" CHECK ("debit_account_id" <> "credit_account_id");

CREATE OR REPLACE FUNCTION reject_financial_history_mutation()
RETURNS trigger AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; create a correction entry instead', TG_TABLE_NAME
    USING ERRCODE = '55000';
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER ledger_entries_append_only
BEFORE UPDATE OR DELETE ON "ledger_entries"
FOR EACH ROW EXECUTE FUNCTION reject_financial_history_mutation();

CREATE TRIGGER wallet_transactions_append_only
BEFORE UPDATE OR DELETE ON "wallet_transactions"
FOR EACH ROW EXECUTE FUNCTION reject_financial_history_mutation();

ALTER TABLE "notification_logs"
  ADD COLUMN "attempt_count" INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN "last_error" TEXT;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM "_prisma_migrations"
    WHERE "migration_name" = '20260814010000_phase3_background_contract'
      AND "finished_at" IS NOT NULL
      AND "rolled_back_at" IS NULL
  ) THEN
    ALTER TABLE "notification_logs"
      RENAME COLUMN "outbox_event_id" TO "outbox_event_id_compat";
    ALTER INDEX "notification_logs_outbox_event_id_channel_key"
      RENAME TO "notification_logs_outbox_event_id_compat_channel_key";
  END IF;
END
$$;

